CREATE OR REPLACE FUNCTION public.select_current_user_organization(target_organization_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
	actor_user_id uuid;
BEGIN
	actor_user_id := NULLIF(
		current_setting('app.current_user_id', true), ''
	)::uuid;
	IF actor_user_id IS NULL OR target_organization_id IS NULL THEN
		RETURN false;
	END IF;

	IF NOT EXISTS (
		SELECT 1
		FROM user_organization_memberships membership
		JOIN organizations organization
		  ON organization.id = membership.organization_id
		WHERE membership.user_id = actor_user_id
		  AND membership.organization_id = target_organization_id
		  AND membership.active
		  AND organization.active
	) THEN
		RETURN false;
	END IF;

	UPDATE users
	SET organization_id = target_organization_id,
		updated_by = actor_user_id,
		updated_at = NOW()
	WHERE id = actor_user_id;

	RETURN FOUND;
END;
